from __future__ import annotations


class APIError(Exception):
    def __init__(self, status_code: int, code: str, message: str) -> None:
        self.status_code = status_code
        self.code = code
        self.message = message
        super().__init__(message)


class NotFoundError(APIError):
    """A referenced dataset, schema version or field does not exist (404)."""

    def __init__(self, message: str) -> None:
        super().__init__(404, "not_found", message)


class ConflictError(APIError):
    """The request conflicts with already stored state (409)."""

    def __init__(self, message: str) -> None:
        super().__init__(409, "conflict", message)


class RequestInvalidError(APIError):
    """The request is structurally or semantically invalid (422)."""

    def __init__(self, message: str) -> None:
        super().__init__(422, "validation_error", message)

def _select_snapshot_at(
    conn: sqlite3.Connection,
    version_id: int,
    target: datetime,
) -> sqlite3.Row | None:
    """The newest snapshot of the version created at or before ``target``.

    Ties are broken by the highest id; comparing parsed instants also handles
    any offset in the target. The sort is explicit (never the database's
    natural order).
    """
    candidates = conn.execute(
        "SELECT id, created_at FROM snapshots WHERE version_id = ?",
        (version_id,),
    ).fetchall()
    eligible = [
        (datetime.fromisoformat(row["created_at"]), row["id"])
        for row in candidates
        if datetime.fromisoformat(row["created_at"]) <= target
    ]
    if not eligible:
        return None
    match_id = max(eligible, key=lambda item: (item[0], item[1]))[1]
    return conn.execute(
        "SELECT id, version_id, row_count, rows, content_hash, created_at "
        "FROM snapshots WHERE id = ?",
        (match_id,),
    ).fetchone()


def _parse_at_timestamp(raw: str) -> datetime:
    try:
        parsed = datetime.fromisoformat(raw)
    except (TypeError, ValueError) as exc:
        raise RequestInvalidError(
            "Query parameter 'timestamp' must be an ISO-8601 date-time"
        ) from exc
    # A trailing timezone designator (offset or 'Z') is mandatory.
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise RequestInvalidError(
            "Query parameter 'timestamp' must include a timezone"
        )
    return parsed


